-- ============================================================
-- IV. HEAVENLY MANDATE PANTHEON (天庭殿)
-- ============================================================

update wf_user.my_frames
set
    cultivation_color    = '#E63946',
    cultivation_school   = 'Heavenly Mandate Pantheon',
    cultivation_identity = 'Heavenly Impaler',
    cultivation_art      = 'Lotus Prince Dao of Wind-Fire Wheels',
    cultivation_doctrine = $doc$Nezha Prime is not a Warframe. He is a direct transplant of the Third Lotus Prince from the Fengshen Yanyi into the Warframe cosmos, and his cultivation practice makes no attempt to disguise this lineage. Fire Walker does not leave a burning trail. It traces the path of the Wind-Fire Wheels -- the legendary artifacts of Nezha of the Lotus that allow their wielder to ride fire across the sky. Blazing Chakram is not a thrown weapon. It is the Universe Ring, the chakram that Nezha used to behead the Dragon King's son, here repurposed as a healing and damage amplification tool because the Heavenly Mandate Pantheon has always understood that divine artifacts contain more functions than their legends record. Divine Spears does not crowd control. It concludes the theological argument that began with Fire Walker: that the Third Lotus Prince does not fight enemies so much as he rearranges the spatial geometry of the encounter until they have no favorable position remaining. Warding Halo does not protect. It halos -- the ring of fire and golden light that marks the Lotus Prince as something the battlefield's rules do not entirely apply to.$doc$
where build_title = 'Heavenly Impaler';

update wf_user.my_frames
set
    cultivation_color    = '#FFB300',
    cultivation_school   = 'Heavenly Mandate Pantheon',
    cultivation_identity = 'Son Goku',
    cultivation_art      = 'Monkey Sage Dao of the Five Immortalities',
    cultivation_doctrine = $doc$Wukong Prime requires no introduction to anyone who has read Journey to the West, because he IS Sun Wukong -- the Great Sage Equal to Heaven, the Monkey King who achieved immortality five separate times through five separate methods, the cultivator who fought the entire celestial bureaucracy to a standstill and lost only because the Buddha changed the rules of engagement. His Iron Staff is the Ruyi Jingu Bang, the pillar that once propped up the Dragon King's ocean now miniaturized to fighting weight. Cloud Walker is Jindouyun, the cloud-somersault that covers 108,000 li in a single bound. Celestial Twin is the hair-clone technique from Chapter 3, the mass-duplication that let Wukong fight armies simultaneously. Primal Fury does not activate. It remembers -- the full combat doctrine of the Monkey Sage surfaces, and everything the celestial court spent three hundred chapters trying to suppress comes back online. The Five Immortalities Dao teaches that the cultivator who cannot be permanently killed has already won every fight they will ever have. Wukong Prime achieved this before the Orokin were a civilization.$doc$
where build_title = 'Son Goku';

update wf_user.my_frames
set
    cultivation_color    = '#1A1A1A',
    cultivation_school   = 'Heavenly Mandate Pantheon',
    cultivation_identity = 'Blade of the Lotus',
    cultivation_art      = 'Umbral Ronin Dao of the Filial Sword',
    cultivation_doctrine = $doc$Excalibur Umbra is the Heavenly Mandate Pantheon's most tragic entry and its most necessary one. He was Dax soldier Isaah's father before the Orokin made him something else -- the Helminth stripped his identity and left the ronin who now carries the weight of having been forced to kill his own son. Slash Dash does not close distance. It expresses a sword doctrine so internalized it has become reflexive, the muscle memory of a man who has been a blade longer than he was a person. Radial Blind does not stun. It creates the moment of silence that a ronin needs -- the half-beat between the encounter and the resolution. Radial Howl is not an upgrade on Radial Blind. It is Umbra's voice, the sound of something that remembers it was a father. Exalted Blade is not Excalibur's signature ability. It is Isaah's inheritance, the sword that the son was supposed to receive, now wielded forever by the father who was made to use it against him. The Umbral Ronin Dao teaches that honor and grief are not opposites. Sometimes they are the same posture, held for the rest of your life.$doc$
where build_title = 'Blade of the Lotus';


-- ============================================================
-- V. STORM HEAVEN CONVOCATION (雷霆天宫)
-- ============================================================

update wf_user.my_frames
set
    cultivation_color    = '#FFD700',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Storm Sovereign',
    cultivation_art      = 'Heavenly Thunder Path of the Voltaic Sovereign',
    cultivation_doctrine = $doc$Volt Prime is the Storm Heaven Convocation's patriarch -- the original lightning cultivator, the Zeus-Lei Gong lineage made Warframe. His cultivation practice is the cleanest expression of the Convocation's founding thesis: that electricity is not a weapon but a medium, and the cultivator who understands this distinction has access to physics that weapon-users do not. Shock does not deal damage. It conducts -- the opening note of a circuit that Volt Prime is constantly completing. Speed does not buff movement. It overclocks the squad's relationship with time, briefly making everyone operate at the frequency Volt Prime considers normal. Electric Shield is not a defensive barrier. It is a voltage differential made architectural: stand behind it and your weapons fire through a field that adds Volt Prime's nature to every projectile. Discharge does not detonate. It broadcasts -- the Voltaic Sovereign asserting that every charged body in range is part of his circuit whether they consented or not. The Heavenly Thunder Path teaches that the cultivator who IS the storm does not need to call lightning. He is already everywhere the lightning goes.$doc$
where build_title = 'Storm Sovereign';

update wf_user.my_frames
set
    cultivation_color    = '#9D4EDD',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Lightning Dancer',
    cultivation_art      = 'Tesla Pirouette Dao of the Coil-Born Empress',
    cultivation_doctrine = $doc$The Storm Heaven Convocation acknowledges natural lightning through Volt Prime and artificial lightning through Gyre Prime, and it treats them as sister arts rather than the same art -- because Pablo and the development team specifically split her from Volt's lineage to make a point. Gyre Prime is not a simplified Volt. She is a ballerina automaton whose body is a Tesla coil, whose every rotation generates the mechanical electricity that the Coil-Born Empress Dao calls the superior form of the art: manufactured, precise, tunable, reproducible. Coil Horizon does not discharge. It broadcasts a specific frequency -- the resonance frequency of the battlefield's ionization state after Gyre Prime has been spinning in it. Cathode Grace does not give her critical chance. It rewards the discipline of maintaining rotational momentum, the pirouette as cultivation practice. Rotorswell does not damage. It accumulates -- the patient buildup of a conductor who understands that the most powerful discharge requires the longest charge. The Tesla Pirouette Dao teaches that the difference between natural and artificial lightning is the same as the difference between a river and an aqueduct: one is more powerful, but only one goes exactly where you need it.$doc$
where build_title = 'Lightning Dancer';

update wf_user.my_frames
set
    cultivation_color    = '#E63946',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Blitz Guardian',
    cultivation_art      = 'Kinetic Velocity Scripture of the Redline Saint',
    cultivation_doctrine = $doc$Gauss Prime is the Storm Heaven Convocation's most extreme position: that speed is not a tactical advantage but a cultivation philosophy, and that the cultivator who has fully committed to velocity has access to a form of physics that stationary fighters cannot reach. Mach Rush does not move Gauss Prime across the battlefield. It conducts a physics experiment -- what happens to kinetic energy when you run it through a body that has been engineered to accumulate rather than dissipate it. Kinetic Plating does not provide damage reduction. It converts incoming kinetic force into battery charge, because the Redline Saint's central teaching is that every hit you take is energy you get to use later. Thermal Sunder does not apply heat and cold. It demonstrates what happens to matter when you run Gauss Prime's accumulated kinetic charge through it in alternating polarity. Redline does not overclock. It completes -- the moment when the battery is full, when all the accumulated velocity and impact and thermal conversion reaches its discharge point, and Gauss Prime briefly operates at the frequency his frame was actually designed for. The Kinetic Velocity Scripture teaches that standing still is always the least efficient thing a cultivator can do.$doc$
where build_title = 'Blitz Guardian';

update wf_user.my_frames
set
    cultivation_color    = '#D4AF37',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Skyfall',
    cultivation_art      = 'Tengu Dao of the Falling Plume',
    cultivation_doctrine = $doc$Zephyr Prime's codename is Tengu -- the Japanese mountain spirit of wind and martial arts -- and her cultivation practice is exactly what that name implies: a sky-bound combat discipline that treats the ground as an optional relationship. Tail Wind does not grant mobility. It establishes the Tengu Dao's fundamental premise: that the cultivator who controls vertical space controls the encounter, because everything dangerous is designed to fight something at ground level. Airburst does not push enemies. It demonstrates aerodynamic authority -- the Falling Plume technique applied to crowd control, wind as architectural force. Turbulence does not reflect projectiles. It wraps Zephyr Prime in a personal weather system that makes the physics of incoming fire disagree with themselves. Tornado does not crowd-control. It concludes the Tengu Dao's argument: that a cultivator who can generate self-sustaining atmospheric vortices does not need to fight the battlefield. She IS the battlefield. The Tengu Dao of the Falling Plume teaches that feathers fall slowly not because they are weak but because they have negotiated a different relationship with gravity than everything else.$doc$
where build_title = 'Skyfall';

update wf_user.my_frames
set
    cultivation_color    = '#B87333',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Spear Master',
    cultivation_art      = 'Hoplite Aegis Dao of the Worthy Spear',
    cultivation_doctrine = $doc$Styanax is the Storm Heaven Convocation's ground-anchor -- the hoplite to Zephyr Prime's Tengu, the cultivator who has decided that the most powerful storm is the one that cannot be moved. His lineage is Astyanax of Troy filtered through the Achaean phalanx tradition: the worthy spear of a civilization that decided the best defensive technology was a wall of men who had decided not to retreat. Axios Javelin does not throw a spear. It adjudicates range -- the hoplite's fundamental tactical calculation: how far can I project force while keeping my formation intact. Final Stand does not rally. It concludes the Hoplite Aegis Dao's central teaching: that the cultivator who calls down javelin storms on their own position has already won the philosophical argument about who owns this piece of ground. Tharros Strike does not debuff enemies. It strips the courage that enemies have borrowed from not yet having met Styanax. Rally Point does not heal or grant energy. It pays dividends on the investment of standing firm -- the phalanx principle that every member who holds makes every other member harder to break.$doc$
where build_title = 'Spear Master';

update wf_user.my_frames
set
    cultivation_color    = '#4A90E2',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Aegis Titan',
    cultivation_art      = 'Shieldmaiden Aegis Dao of the Balefire Storm',
    cultivation_doctrine = $doc$Hildryn Prime runs on shields the way other cultivators run on energy, and the Storm Heaven Convocation has always understood this as a theological position rather than a mechanical one: that the cultivator who has decided to make protection itself into power has access to an entirely different kind of strength. Haven does not protect allies. It extends Hildryn Prime's shield economy across the squad, making everyone a node in the Aegis network. Pillage does not strip enemy armor and shields. It harvests -- the Shieldmaiden's fundamental transaction: your defenses become my defenses, because in the Aegis Dao, all shields belong to the person who needs them most. Balefire Charger does not deal damage. It converts shield overage into Norse lightning-pistol fire, because Hildryn Prime has Norse Valkyrie lineage (Hildr, the battle-maiden who chose the slain) and her excess protection must go somewhere. Aegis Storm does not create a zone of crowd control and damage. It expresses the Shieldmaiden's complete doctrine: aerial barrage delivered from a position of absolute defensive superiority, the Norse battle-maiden who has decided that the sky belongs to her shields.$doc$
where build_title = 'Aegis Titan';

update wf_user.my_frames
set
    cultivation_color    = '#A8DADC',
    cultivation_school   = 'Storm Heaven Convocation',
    cultivation_identity = 'Star of Polarity',
    cultivation_art      = 'Polar Star Sutra of the Magnetar''s Embrace',
    cultivation_doctrine = $doc$Mag Prime is the Storm Heaven Convocation's cosmologist -- the cultivator whose art operates not at the scale of weather or velocity but at the scale of fundamental forces. Her lineage is the magnetar: the neutron star variant that generates the most powerful magnetic fields in the observable universe, the astronomical object whose influence distorts the physics of everything within its range. Pull does not drag enemies toward Mag Prime. It demonstrates the Polar Star Sutra's opening lesson: that the cultivator who controls magnetic force controls the geometry of every metallic and electrically-charged object in range. Magnetize does not create a singularity. It applies the Magnetar's Embrace to a single target -- a localized demonstration of what happens when you concentrate the Sun's magnetic field into an area the size of a head. Polarize does not strip armor. It conducts a field reversal through the battlefield's magnetic state, and the armor shattering and shield charging are byproducts of the physics, not the intention. Crush does not kill. It concludes -- the Magnetar's Embrace applied at full scale, the moment when Mag Prime stops demonstrating and starts asserting that the magnetic field is, always has been, and will remain hers.$doc$
where build_title = 'Star of Polarity';
